function Assert-NativeArchitecture {
  param([string]$Path, [ValidateSet('x86','x64')][string]$Architecture)
  $bytes = [IO.File]::ReadAllBytes($Path)
  if ($bytes.Length -lt 64) { throw "Truncated native test binary: $Path" }
  $offset = [BitConverter]::ToInt32($bytes, 60)
  if ($offset -lt 64 -or $offset -gt $bytes.Length - 6 -or
      [BitConverter]::ToUInt32($bytes, $offset) -ne 0x00004550) {
    throw "Invalid PE native test binary: $Path"
  }
  $expected = if ($Architecture -eq 'x86') { 0x014c } else { 0x8664 }
  $actual = [BitConverter]::ToUInt16($bytes, $offset + 4)
  if ($actual -ne $expected) { throw "Native test architecture mismatch: $Path expected=$Architecture machine=$actual" }
  Write-Host "NATIVE_ARCH_PASS architecture=$Architecture path=$Path"
}
